head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//발행기관 회사명변경 현황 상세정보
scwin.vScrenID = "ULDINS91800.xml";
scwin.param1 = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/********************************************** 
 * 함수명   : ins_search
 * 설명       : 발행기관 회사명변경 현황 상세정보
 ***********************************************/
scwin.ins_search = function() {
    // 회사명 변경내역 
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS25000_CHGLIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.download.select.listDownloadIsurChgInfoInquiry" + "&{P}param01=" + scwin.param1 + "&{P}param02=" + scwin.param1;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기 

};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_search_onclick = function() {
    scwin.ins_search(txb_INST_NM.getValue(), rdo_MKT_ID.getValue());
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.gform_onload = function() {
    var arrPar = new Array();
    var parentWin = $c.frame.path("../");
    var fn_GetPar = parentWin.fn_GetParam;
    if (fn_GetPar != undefined) {
        fn_GetPar(arrPar);
        scwin.param1 = ((arrPar.length >= 1) && (arrPar[0] != undefined) ? arrPar[0] : "");
        scwin.ins_search();
    }
};
